function parseRecipe(d, idx) {
  const id = `western-${idx + 83}-${d[0].toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0,35)}`;
  return { id, name: d[0], category: 'Western', description: d[7], ingredients: d[8].split(',').map(s=>s.trim()).filter(Boolean), steps: d[9].split(/\.\s*/).map(s=>s.trim()).filter(s=>s.length>5), cookTime: d[2], prepTime: d[3], servings: d[4], difficulty: d[1], calories: d[5], image: '', tags: d[6].split(',').map(t=>t.trim()) };
}

const recipes = mainCourses.map((r, i) => parseRecipe(r, i));
const content = `import type { Recipe } from '@/types';

export const westernRecipes2: Recipe[] = [\n${recipes.map((r, i) => '  ' + JSON.stringify(r, null, 2).split('\n').join('\n  ') + (i < recipes.length - 1 ? ',' : '')).join('\n')}\n];

export const westernRecipes2Count = ${recipes.length};\n`;

const outPath = path.join(__dirname, '..', 'src', 'lib', 'recipes', 'recipes-western-2.ts');
fs.writeFileSync(outPath, content, 'utf8');
console.log(`Generated ${recipes.length} Western main course recipes`);
